<script setup lang="ts">
import {safeHref} from '../lib/navigation-links';
import { computed, onScopeDispose, ref } from 'vue';
import { latestNews } from '../api/latest-news';
import {newsBookmarkKey} from '../lib/news-links';
import type { LatestNews } from '../api/latest-news';
import { useResource } from '../composables/useResource';
import { usePage } from '../composables/usePage';
import LatestRacePhoto from './LatestRacePhoto.vue';
import {publicReference} from '../lib/urls';
import ResourceState from './ResourceState.vue';
const { t, locale, preferences } = usePage();
const props = defineProps<{ compact?: boolean }>();
const search = ref('');
const { data, loading, error, retryAfter, reload } = useResource(latestNews, [], {publicCacheKey:"latest-news", volatile: true, preserveWhileRefreshing: true });
const now = ref(Date.now());
const timer = setInterval(() => { now.value = Date.now(); }, 1000);
onScopeDispose(() => clearInterval(timer));
const fresh = computed(() => data.value?.status === 'ready' && Date.parse(data.value.expiresAt!) > now.value);
const items = computed(() => fresh.value ? data.value!.items.filter(item => [item.title,item.titleZh,item.summaryZh].some(text=>text?.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()))).slice(0, props.compact ? 5 : 20) : []);
const headline = (item: LatestNews['items'][number]) => locale.value === 'zh-CN' ? item.titleZh || t('latest.translationUnavailable') : item.title;
const summary = (item: LatestNews['items'][number]) => locale.value === 'zh-CN' ? item.summaryZh : item.summary;
const oldSource = computed(() => fresh.value && data.value?.newestPublishedAt && now.value - Date.parse(data.value.newestPublishedAt) > 72 * 3600000);
const stamp = (value: string) => new Intl.DateTimeFormat(locale.value, { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', timeZoneName: 'short', timeZone: preferences.timeZone }).format(new Date(value));
</script>
<template><section class="latest-news-panel" aria-labelledby="latest-heading" data-testid="latest-news"><div class="section-heading"><div><p class="eyebrow">{{publicReference?'RACE BRIEFS / F1DB':'F1 NEWS / RSS'}}</p><h2 id="latest-heading">{{ t(publicReference?'publicData.newsTitle':'latest.title') }}</h2></div><a class="button" :href="safeHref(publicReference?'https://github.com/f1db/f1db':'https://www.bbc.co.uk/sport/formula1')" :target="(safeHref(publicReference?'https://github.com/f1db/f1db':'https://www.bbc.co.uk/sport/formula1'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{publicReference?'F1DB':'BBC Sport'}} ↗</a></div><p class="muted">{{ t(publicReference?'publicData.newsDescription':'latest.description') }}</p><LatestRacePhoto v-if="!compact"/><p class="caption latest-usage">{{ t(publicReference?'publicData.newsUsage':'latest.personal') }} <a :href="safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://www.bbc.co.uk/sport/articles/cqllxj2n4kyo')" :target="(safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://www.bbc.co.uk/sport/articles/cqllxj2n4kyo'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{ t('latest.terms') }} ↗</a></p><ResourceState :loading="loading && !data" :focus-on-load="false" :error="error" :retry-after="retryAfter" @retry="reload"><template v-if="data"><div v-if="fresh" class="latest-metadata"><span>{{ t('latest.attribution') }} <a :href="safeHref(data.sourceUrl)" :target="(safeHref(data.sourceUrl))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{data.sourceName}}</a></span><span>{{ t('latest.synced') }} <time :datetime="data.syncedAt!">{{ stamp(data.syncedAt!) }}</time></span><span>{{ t(publicReference?'publicData.interval':'latest.interval') }}</span></div><p v-else class="notice" role="status">{{ t('latest.' + (data.status === 'ready' ? 'pending' : data.status)) }}</p><p v-if="oldSource" class="notice" role="status">{{ t('latest.oldSource') }}</p><label v-if="fresh && !compact" class="latest-search"><span>{{ t('latest.search') }}</span><input v-model="search" type="search" maxlength="100" :placeholder="t('latest.searchHint')"/></label><ol v-if="items.length" class="latest-items"><li v-for="item in items" :key="item.url"><div><p class="caption">{{data.sourceName}} · <time v-if="item.publishedAt" :datetime="item.publishedAt">{{ stamp(item.publishedAt) }}</time><span v-else>{{ t('official.noDate') }}</span></p><a :href="safeHref(publicReference?'#/brief?source='+encodeURIComponent(item.url):item.url)" :target="publicReference?undefined:'_blank'" rel="noopener noreferrer" class="latest-headline" :lang="locale">{{ headline(item) }} <span aria-hidden="true">↗</span></a><p v-if="summary(item)" class="latest-summary">{{ summary(item) }}</p><p v-if="locale === 'zh-CN'" class="caption">{{ t(item.translationStatus==='original'?'publicData.original':item.translationStatus === 'edited' ? 'latest.edited' : item.translationStatus === 'machine' ? 'latest.machine' : 'latest.translationUnavailable') }} · {{ t('latest.summaryOnly') }}</p><details v-if="locale === 'zh-CN'" class="news-original"><summary>{{ t('latest.original') }}</summary><p lang="en">{{ item.title }}</p><p lang="en">{{ item.summary }}</p></details></div><div class="latest-actions"><button type="button" :aria-pressed="preferences.savedNewsUrls.includes(newsBookmarkKey(item.url)!)" :aria-label="t(preferences.savedNewsUrls.includes(newsBookmarkKey(item.url)!)?'world.unsaveNamed':'world.saveNamed',{title:headline(item)})" @click="preferences.toggleNews(item.url)">{{t(preferences.savedNewsUrls.includes(newsBookmarkKey(item.url)!)?'news.saved':'news.save')}}</button><a :href="safeHref(publicReference?'#/brief?source='+encodeURIComponent(item.url):item.url)" class="latest-read" :target="publicReference?undefined:'_blank'" rel="noopener noreferrer" :aria-label="t(publicReference?'publicData.read':'latest.read') + ': ' + headline(item)">{{ t(publicReference?'community.readBrief':'latest.read') }} ↗</a></div></li></ol><p v-else-if="fresh" class="empty-inline" role="status">{{ t(search ? 'latest.noMatches' : 'latest.empty') }}</p></template></ResourceState><RouterLink v-if="compact && fresh" class="button" to="/news">{{ t('latest.viewAll') }} →</RouterLink><p class="caption latest-source-note">{{ t(publicReference?'publicData.newsUsage':'latest.sourceNote') }} <a :href="safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://www.bbc.co.uk/usingthebbc/terms-of-use/#15metadataandrssfeeds')" :target="(safeHref(publicReference?'https://creativecommons.org/licenses/by/4.0/':'https://www.bbc.co.uk/usingthebbc/terms-of-use/#15metadataandrssfeeds'))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{ t('latest.terms') }} ↗</a></p></section></template>
